import React, { useState, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Type } from "@google/genai";
import * as docx from "https://cdn.skypack.dev/docx";

// --- Types ---

interface DocxContent {
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
}

interface AnalysisResult {
  image_description: string;
  docx_content: DocxContent;
}

// --- Constants ---

const SYSTEM_INSTRUCTION = `You are an educational content generator for English exams.

A teacher will input a multiple-choice question about signs or notices.
The content inside square brackets [ ] describes the sign.

Your task:

Analyze the meaning of the sign based ONLY on the text inside [ ].

Create a clear and simple IMAGE DESCRIPTION that can be used to generate an illustration of the sign.

Style: flat, simple, exam-friendly
Colors: clear contrast (red, black, white if prohibition)
No text explanation inside the image except the sign wording if appropriate

Prepare structured content for exporting to a DOCX file with the following layout:
Left side: the generated image
Right side: the question text and options A–D

Output your response in JSON format only, following this exact structure:

{
  "image_description": "...",
  "docx_content": {
    "question": "...",
    "options": {
      "A": "...",
      "B": "...",
      "C": "...",
      "D": "..."
    }
  }
}

Do NOT explain your reasoning.
Do NOT add extra text outside the JSON.`;

// --- App Component ---

const App = () => {
  const [inputText, setInputText] = useState<string>(
    "[NO PARKING] You must not park here.\nA. True\nB. False\nC. Only on Sundays\nD. Only for staff"
  );
  const [loadingStep, setLoadingStep] = useState<
    "idle" | "analyzing" | "drawing" | "done"
  >("idle");
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(
    null
  );
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!inputText.trim()) return;

    setLoadingStep("analyzing");
    setError(null);
    setAnalysisResult(null);
    setImageUrl(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        throw new Error("API Key not found in environment.");
      }

      const ai = new GoogleGenAI({ apiKey });

      // 1. Analyze Text
      const analysisModel = "gemini-3-flash-preview";
      const analysisResponse = await ai.models.generateContent({
        model: analysisModel,
        contents: inputText,
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              image_description: { type: Type.STRING },
              docx_content: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: {
                    type: Type.OBJECT,
                    properties: {
                      A: { type: Type.STRING },
                      B: { type: Type.STRING },
                      C: { type: Type.STRING },
                      D: { type: Type.STRING },
                    },
                    required: ["A", "B", "C", "D"],
                  },
                },
                required: ["question", "options"],
              },
            },
            required: ["image_description", "docx_content"],
          },
        },
      });

      const jsonText = analysisResponse.text;
      if (!jsonText) throw new Error("No analysis response generated.");

      const result: AnalysisResult = JSON.parse(jsonText);
      setAnalysisResult(result);

      // 2. Generate Image
      setLoadingStep("drawing");

      const imagePrompt = `A flat, simple, educational vector illustration of a sign: ${result.image_description}. High contrast, clean lines, white background. Professional exam style.`;

      const imageModel = "gemini-2.5-flash-image";
      const imageResponse = await ai.models.generateContent({
        model: imageModel,
        contents: imagePrompt,
        config: {
          imageConfig: {
            aspectRatio: "1:1",
          },
        },
      });

      // Find image part
      let foundImage = false;
      if (imageResponse.candidates && imageResponse.candidates[0].content.parts) {
        for (const part of imageResponse.candidates[0].content.parts) {
          if (part.inlineData) {
            const base64Data = part.inlineData.data;
            const mimeType = part.inlineData.mimeType || "image/png";
            setImageUrl(`data:${mimeType};base64,${base64Data}`);
            foundImage = true;
            break;
          }
        }
      }

      if (!foundImage) {
        throw new Error("No image generated by the model.");
      }

      setLoadingStep("done");
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred.");
      setLoadingStep("idle");
    }
  };

  const handleDownloadDocx = async () => {
    if (!analysisResult || !imageUrl) return;

    try {
      // Convert base64 data url to blob/buffer for docx
      const response = await fetch(imageUrl);
      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();

      const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, ImageRun } = docx;

      const doc = new Document({
        sections: [
          {
            properties: {},
            children: [
              new Paragraph({
                children: [
                  new TextRun({
                    text: "English Exam - Sign Analysis",
                    bold: true,
                    size: 32,
                  }),
                ],
                spacing: { after: 400 },
              }),
              new Table({
                width: {
                  size: 100,
                  type: WidthType.PERCENTAGE,
                },
                rows: [
                  new TableRow({
                    children: [
                      // Cell 1: Image
                      new TableCell({
                        width: {
                          size: 40,
                          type: WidthType.PERCENTAGE,
                        },
                        children: [
                          new Paragraph({
                            children: [
                              new ImageRun({
                                data: arrayBuffer,
                                transformation: {
                                  width: 200,
                                  height: 200,
                                },
                              }),
                            ],
                          }),
                        ],
                      }),
                      // Cell 2: Question and Options
                      new TableCell({
                        width: {
                          size: 60,
                          type: WidthType.PERCENTAGE,
                        },
                        margins: {
                          left: 400,
                        },
                        children: [
                          new Paragraph({
                            children: [
                              new TextRun({
                                text: analysisResult.docx_content.question,
                                bold: true,
                                size: 24,
                              }),
                            ],
                            spacing: { after: 200 },
                          }),
                          ...Object.entries(analysisResult.docx_content.options).map(
                            ([key, value]) =>
                              new Paragraph({
                                children: [
                                  new TextRun({
                                    text: `${key}. ${value}`,
                                    size: 24,
                                  }),
                                ],
                              })
                          ),
                        ],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          },
        ],
      });

      const buffer = await Packer.toBlob(doc);
      const url = window.URL.createObjectURL(buffer);
      const a = document.createElement("a");
      a.href = url;
      a.download = "exam-question.docx";
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error("Error creating DOCX:", e);
      setError("Failed to create DOCX file.");
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 p-8">
      <div className="max-w-5xl mx-auto space-y-8">

        {/* Header */}
        <header className="border-b pb-4 border-gray-200">
          <h1 className="text-3xl font-bold text-gray-900">Sign Exam Generator</h1>
          <p className="text-gray-500 mt-2">
            Enter a question with a [Sign Description] to generate exam content.
          </p>
        </header>

        {/* Input Section */}
        <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <label htmlFor="questionInput" className="block text-sm font-medium text-gray-700 mb-2">
            Input Question
          </label>
          <textarea
            id="questionInput"
            className="w-full h-32 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
            placeholder="e.g., [NO ENTRY] You cannot enter this road. A. True B. False..."
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
          />

          <div className="mt-4 flex items-center justify-end">
             <button
              onClick={handleGenerate}
              disabled={loadingStep === "analyzing" || loadingStep === "drawing"}
              className={`px-6 py-2 rounded-md text-white font-medium transition-colors ${
                 loadingStep === "analyzing" || loadingStep === "drawing"
                  ? "bg-gray-400 cursor-not-allowed"
                  : "bg-indigo-600 hover:bg-indigo-700"
              }`}
            >
              {loadingStep === "analyzing" && "Analyzing Text..."}
              {loadingStep === "drawing" && "Generating Sign Image..."}
              {loadingStep === "idle" || loadingStep === "done" ? "Generate Content" : ""}
            </button>
          </div>
        </section>

        {/* Error Display */}
        {error && (
          <div className="bg-red-50 text-red-700 p-4 rounded-md border border-red-200">
            <strong>Error:</strong> {error}
          </div>
        )}

        {/* Results Section */}
        {analysisResult && (
          <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
            <div className="flex justify-between items-center mb-6">
               <h2 className="text-xl font-semibold text-gray-800">Preview</h2>
               {imageUrl && (
                 <button
                   onClick={handleDownloadDocx}
                   className="flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 text-gray-700 font-medium transition"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                   </svg>
                   <span>Download DOCX</span>
                 </button>
               )}
            </div>

            <div className="flex flex-col md:flex-row gap-8">
              {/* Left Column: Image */}
              <div className="w-full md:w-1/3 flex flex-col items-center">
                <div className="text-sm font-medium text-gray-500 mb-2 w-full">Generated Sign</div>
                <div className="w-full aspect-square bg-gray-100 rounded-md border border-gray-200 flex items-center justify-center overflow-hidden relative">
                   {imageUrl ? (
                     <img src={imageUrl} alt="Generated Sign" className="w-full h-full object-contain p-4" />
                   ) : (
                     <div className="flex flex-col items-center text-gray-400 animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <span>Loading image...</span>
                     </div>
                   )}
                </div>
                <div className="mt-4 p-3 bg-blue-50 text-blue-800 text-xs rounded border border-blue-100 w-full">
                  <strong>AI Description:</strong> {analysisResult.image_description}
                </div>
              </div>

              {/* Right Column: Text */}
              <div className="w-full md:w-2/3">
                 <div className="text-sm font-medium text-gray-500 mb-2">Structured Content</div>
                 <div className="p-6 border border-gray-200 rounded-md bg-gray-50 h-full">
                    <p className="text-lg font-bold mb-6">{analysisResult.docx_content.question}</p>
                    <div className="space-y-3">
                      {Object.entries(analysisResult.docx_content.options).map(([key, val]) => (
                        <div key={key} className="flex items-start">
                          <span className="font-semibold w-8 flex-shrink-0">{key}.</span>
                          <span>{val}</span>
                        </div>
                      ))}
                    </div>
                 </div>
              </div>
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(<App />);

