  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 p-8">
      <div className="max-w-5xl mx-auto space-y-8">

        {/* Header */}
        <header className="border-b pb-4 border-gray-200">
          <h1 className="text-3xl font-bold text-gray-900">Sign Exam Generator</h1>
          <p className="text-gray-500 mt-2">
            Enter a question with a [Sign Description] to generate exam content.
          </p>
        </header>

        {/* Input Section */}
        <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <label htmlFor="questionInput" className="block text-sm font-medium text-gray-700 mb-2">
            Input Question
          </label>
          <textarea
            id="questionInput"
            className="w-full h-32 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
            placeholder="e.g., [NO ENTRY] You cannot enter this road. A. True B. False..."
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
          />

          <div className="mt-4 flex items-center justify-end">
             <button
              onClick={handleGenerate}
              disabled={loadingStep === "analyzing" || loadingStep === "drawing"}
              className={`px-6 py-2 rounded-md text-white font-medium transition-colors ${
                 loadingStep === "analyzing" || loadingStep === "drawing"
                  ? "bg-gray-400 cursor-not-allowed"
                  : "bg-indigo-600 hover:bg-indigo-700"
              }`}
            >
              {loadingStep === "analyzing" && "Classifying & Analyzing..."}
              {loadingStep === "drawing" && "Generating Illustration..."}
              {loadingStep === "idle" || loadingStep === "done" ? "Generate Content" : ""}
            </button>
          </div>
        </section>

        {/* Error Display */}
        {error && (
          <div className="bg-red-50 text-red-700 p-4 rounded-md border border-red-200">
            <strong>Error:</strong> {error}
          </div>
        )}

        {/* Results Section */}
        {analysisResult && (
          <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
            <div className="flex justify-between items-center mb-6">
               <div className="flex items-center gap-3">
                 <h2 className="text-xl font-semibold text-gray-800">Preview</h2>
                 <span className={`px-2 py-1 text-xs font-bold uppercase rounded ${
                   analysisResult.type === 'sign' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                 }`}>
                   Detected: {analysisResult.type}
                 </span>
               </div>
               {imageUrl && (
                 <button
                   onClick={handleDownloadDocx}
                   className="flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 text-gray-700 font-medium transition"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                   </svg>
                   <span>Download DOCX</span>
                 </button>
               )}
            </div>

            <div className="flex flex-col md:flex-row gap-8">
              {/* Left Column: Image */}
              <div className="w-full md:w-1/2 flex flex-col items-center">
                <div className="text-sm font-medium text-gray-500 mb-2 w-full">Generated Illustration</div>
                <div className={`w-full bg-gray-100 rounded-md border border-gray-200 flex items-center justify-center overflow-hidden relative ${
                    analysisResult.type === "notice" ? "aspect-video" : "aspect-square"
                }`}>
                   {imageUrl ? (
                     <img src={imageUrl} alt="Generated Sign" className="w-full h-full object-contain p-4" />
                   ) : (
                     <div className="flex flex-col items-center text-gray-400 animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <span>Loading image...</span>
                     </div>
                   )}
                </div>
                <div className="mt-4 p-3 bg-blue-50 text-blue-800 text-xs rounded border border-blue-100 w-full">
                  <strong>AI Description:</strong> {analysisResult.image_description}
                </div>
              </div>

              {/* Right Column: Text */}
              <div className="w-full md:w-1/2">
                 <div className="text-sm font-medium text-gray-500 mb-2">Structured Content</div>
                 <div className="p-6 border border-gray-200 rounded-md bg-gray-50 h-full">
                    <p className="text-lg font-bold mb-6">{analysisResult.docx_content.question}</p>
                    <div className="space-y-3">
                      {Object.entries(analysisResult.docx_content.options).map(([key, val]) => (
                        <div key={key} className="flex items-start">
                          <span className="font-semibold w-8 flex-shrink-0">{key}.</span>
                          <span>{val}</span>
                        </div>
                      ))}
                    </div>
                 </div>
              </div>
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(<App />);

import React, { useState, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Type } from "@google/genai";
import * as docx from "https://esm.sh/docx@8.5.0";

// --- Types ---

interface DocxContent {
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
}

interface AnalysisResult {
  type: "sign" | "notice";
  image_description: string;
  docx_content: DocxContent;
}

// --- Constants ---

const SYSTEM_INSTRUCTION = `You are an educational content generator for English exams.

A teacher will input a multiple-choice question about signs or notices.
The content inside square brackets [ ] is the primary subject.

Your task is a 3-step process:

Step 1: Classification
Identify the type based ONLY on the text inside [ ]:
- "sign": Short, rule-based, command or prohibition. Usually noun phrases or imperatives (e.g., NO PARKING, KEEP OFF).
- "notice": Informational message written in full sentences. Often includes time, reason, or future action (e.g., Closed for renovation. Will reopen next week).

Step 2: Image Description
Create a clear image description suitable for generating an illustration.
- If "sign": Describe a flat, symbolic design with strong visual icons. Minimal or no sentences. High contrast (e.g., Red circle for prohibition).
- If "notice": Describe a simple rectangular notice. You MUST explicitly state the exact text content to be written on the sign (e.g., "A notice with the text: 'Library Closed'"). Focus on the text content.

Step 3: Content Extraction
Prepare structured content for exporting to a DOCX file with the following layout:
Left side: the generated image
Right side: the question text and options A–D

Output your response in JSON format only, following this exact structure:

{
  "type": "sign" | "notice",
  "image_description": "...",
  "docx_content": {
    "question": "...",
    "options": {
      "A": "...",
      "B": "...",
      "C": "...",
      "D": "..."
    }
  }
}

Do NOT explain your reasoning.
Do NOT add extra text outside the JSON.`;

const REFERENCE_ANALYSIS_INSTRUCTION = `You are an assistant for an English teacher. 
The teacher will upload an image of a real-world Sign or Notice.

Your task:
1. Analyze the image to determine if it is a "Sign" (command/symbolic) or a "Notice" (informational text).
2. Generate 5 NEW, SIMILAR exam questions based on the style and context of the image.
3. Each suggestion must follow this exact format:
   "[Description of sign content] The question text...
    A. Option 1
    B. Option 2
    C. Option 3
    D. Option 4"

Return the result as a JSON Object containing an array of strings named "suggestions".`;

// --- App Component ---

const App = () => {
  // Tabs: 'manual' is the existing flow, 'upload' is the new feature
  const [activeTab, setActiveTab] = useState<"manual" | "upload">("manual");

  // Existing State
  const [inputText, setInputText] = useState<string>(
    "[The garden is closed for planting. Will be open to visitors next week] The notice says...\nA. You can visit anytime.\nB. Visitors are allowed now.\nC. Closed for planting.\nD. Open after planting."
  );
  const [loadingStep, setLoadingStep] = useState<
    "idle" | "analyzing" | "drawing" | "done"
  >("idle");
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(
    null
  );
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // New State for Upload Feature
  const [referenceImage, setReferenceImage] = useState<string | null>(null);
  const [isAnalyzingRef, setIsAnalyzingRef] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Helper: Convert Blob to Base64 ---
  const fileToGenerativePart = async (file: File) => {
    const base64EncodedDataPromise = new Promise<string>((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve((reader.result as string).split(",")[1]);
      reader.readAsDataURL(file);
    });
    return {
      inlineData: {
        data: await base64EncodedDataPromise,
        mimeType: file.type,
      },
    };
  };

  // --- New Feature: Analyze Reference Image ---
  const handleReferenceUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Show preview
    const reader = new FileReader();
    reader.onload = (e) => setReferenceImage(e.target?.result as string);
    reader.readAsDataURL(file);

    setIsAnalyzingRef(true);
    setSuggestions([]);
    setError(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key not found.");

      const ai = new GoogleGenAI({ apiKey });
      const model = ai.getGenerativeModel({ model: "gemini-3-flash-preview" });

      const imagePart = await fileToGenerativePart(file);

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: {
          parts: [
            imagePart,
            { text: "Analyze this image and generate 5 similar exam questions." }
          ]
        },
        config: {
          systemInstruction: REFERENCE_ANALYSIS_INSTRUCTION,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestions: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            }
          }
        }
      });

      const result = JSON.parse(response.text || "{}");
      if (result.suggestions && Array.isArray(result.suggestions)) {
        setSuggestions(result.suggestions);
      } else {
        throw new Error("Failed to generate suggestions.");
      }

    } catch (err: any) {
      console.error(err);
      setError("Failed to analyze image. Please try again.");
    } finally {
      setIsAnalyzingRef(false);
    }
  };

  const handleSelectSuggestion = (suggestion: string) => {
    setInputText(suggestion);
    setActiveTab("manual");
    setSuggestions([]);
    setReferenceImage(null);
    // Optional: Reset file input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  // --- Existing Logic: Generate Content ---
  const handleGenerate = async () => {
    if (!inputText.trim()) return;

    setLoadingStep("analyzing");
    setError(null);
    setAnalysisResult(null);
    setImageUrl(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        throw new Error("API Key not found in environment.");
      }

      const ai = new GoogleGenAI({ apiKey });

      // 1. Analyze Text & Classify
      const analysisModel = "gemini-3-flash-preview";
      const analysisResponse = await ai.models.generateContent({
        model: analysisModel,
        contents: inputText,
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              type: { type: Type.STRING, enum: ["sign", "notice"] },
              image_description: { type: Type.STRING },
              docx_content: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: {
                    type: Type.OBJECT,
                    properties: {
                      A: { type: Type.STRING },
                      B: { type: Type.STRING },
                      C: { type: Type.STRING },
                      D: { type: Type.STRING },
                    },
                    required: ["A", "B", "C", "D"],
                  },
                },
                required: ["question", "options"],
              },
            },
            required: ["type", "image_description", "docx_content"],
          },
        },
      });

      const jsonText = analysisResponse.text;
      if (!jsonText) throw new Error("No analysis response generated.");

      const result: AnalysisResult = JSON.parse(jsonText);
      setAnalysisResult(result);

      // 2. Generate Image based on Type
      setLoadingStep("drawing");

      const isNotice = result.type === "notice";
      let imagePrompt = "";

      if (isNotice) {
        // Notice style: Optimized for maximum text legibility
        imagePrompt = `A digital illustration of a simple rectangular NOTICE SIGN. 
        Content: ${result.image_description}.

        CRITICAL VISUAL RULES:
        1. TEXT PRIORITY: The text must be VERY LARGE, BOLD, and BLACK.
        2. FONT: Use a clean, heavy Sans-Serif font (like Arial Bold).
        3. LAYOUT: The text must fill 90% of the image space. Center aligned.
        4. BACKGROUND: Plain white or pale yellow. High contrast against the text.
        5. STYLE: Flat 2D vector. No realistic shading. No background scenery. No glare.

        The goal is for a student to easily read the text on an exam paper.`;
      } else {
        // Sign style: Symbolic, icon-based, minimal text
        imagePrompt = `A flat, simple, educational vector illustration of a SYMBOLIC SIGN: ${result.image_description}. High contrast, clean lines, strong visual icons, no background clutter. Professional exam style.`;
      }

      const imageModel = "gemini-2.5-flash-image";
      const imageResponse = await ai.models.generateContent({
        model: imageModel,
        contents: imagePrompt,
        config: {
          imageConfig: {
            aspectRatio: isNotice ? "16:9" : "1:1", // 16:9 gives more width for sentence-based notices
          },
        },
      });

      // Find image part
      let foundImage = false;
      if (imageResponse.candidates && imageResponse.candidates[0].content.parts) {
        for (const part of imageResponse.candidates[0].content.parts) {
          if (part.inlineData) {
            const base64Data = part.inlineData.data;
            const mimeType = part.inlineData.mimeType || "image/png";
            setImageUrl(`data:${mimeType};base64,${base64Data}`);
            foundImage = true;
            break;
          }
        }
      }

      if (!foundImage) {
        throw new Error("No image generated by the model.");
      }

      setLoadingStep("done");
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred.");
      setLoadingStep("idle");
    }
  };

  const handleDownloadDocx = async () => {
    if (!analysisResult || !imageUrl) return;

    try {
      // 1. Fetch image and process binary data
      const response = await fetch(imageUrl);
      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      // Crucial fix: Convert ArrayBuffer to Uint8Array for docx library
      const imageUint8Array = new Uint8Array(arrayBuffer);

      // Determine image type (default to PNG if unsure)
      const mimeType = blob.type; 
      // docx library expects simple strings like "png", "jpeg", "gif"
      // If generated image is png, use "png", if jpeg, use "jpeg"
      const docxImageType = mimeType.includes("jpeg") || mimeType.includes("jpg") 
        ? "jpeg" 
        : "png";

      const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, ImageRun } = docx;

      // Calculate height based on aspect ratio (Width fixed at 200px approx)
      // 1:1 -> 200px height
      // 16:9 -> ~113px height
      const imageHeight = analysisResult.type === "notice" ? 113 : 200;

      const doc = new Document({
        sections: [
          {
            properties: {},
            children: [
              new Paragraph({
                children: [
                  new TextRun({
                    text: "English Exam - Sign Analysis",
                    bold: true,
                    size: 32, // 16pt
                  }),
                ],
                spacing: { after: 400 },
              }),
              new Table({
                width: {
                  size: 100,
                  type: WidthType.PERCENTAGE,
                },
                rows: [
                  new TableRow({
                    children: [
                      // Cell 1: Image
                      new TableCell({
                        width: {
                          size: 45, // Slightly wider column for image to accommodate 16:9 better
                          type: WidthType.PERCENTAGE,
                        },
                        children: [
                          new Paragraph({
                            children: [
                              new ImageRun({
                                data: imageUint8Array,
                                transformation: {
                                  width: 200,
                                  height: imageHeight, 
                                },
                                type: docxImageType,
                              }),
                            ],
                          }),
                        ],
                      }),
                      // Cell 2: Question and Options
                      new TableCell({
                        width: {
                          size: 55,
                          type: WidthType.PERCENTAGE,
                        },
                        margins: {
                          left: 200, // Twips
                        },
                        children: [
                          new Paragraph({
                            children: [
                              new TextRun({
                                text: analysisResult.docx_content.question,
                                bold: true,
                                size: 24, // 12pt
                              }),
                            ],
                            spacing: { after: 200 },
                          }),
                          ...Object.entries(analysisResult.docx_content.options).map(
                            ([key, value]) =>
                              new Paragraph({
                                children: [
                                  new TextRun({
                                    text: `${key}. ${value}`,
                                    size: 24, // 12pt
                                  }),
                                ],
                              })
                          ),
                        ],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          },
        ],
      });

      const buffer = await Packer.toBlob(doc);
      const url = window.URL.createObjectURL(buffer);
      const a = document.createElement("a");
      a.href = url;
      a.download = "exam-question.docx";
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error("Error creating DOCX:", e);
      setError("Failed to create DOCX file.");
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 p-8">
      <div className="max-w-5xl mx-auto space-y-8">

        {/* Header */}
        <header className="border-b pb-4 border-gray-200">
          <h1 className="text-3xl font-bold text-gray-900">Sign Exam Generator</h1>
          <p className="text-gray-500 mt-2">
            Create exam questions from text descriptions or by analyzing real images.
          </p>
        </header>

        {/* Mode Tabs */}
        <div className="flex space-x-4 border-b border-gray-200">
          <button
            onClick={() => setActiveTab("manual")}
            className={`pb-2 px-4 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "manual"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            Manual Input
          </button>
          <button
            onClick={() => setActiveTab("upload")}
            className={`pb-2 px-4 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "upload"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            Upload Reference Image
          </button>
        </div>

        {/* Input Section - Swaps based on Active Tab */}
        <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">

          {activeTab === "manual" ? (
            // MANUAL INPUT MODE (Existing)
            <div>
              <label htmlFor="questionInput" className="block text-sm font-medium text-gray-700 mb-2">
                Input Question
              </label>
              <textarea
                id="questionInput"
                className="w-full h-32 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
                placeholder="e.g., [NO ENTRY] You cannot enter this road. A. True B. False..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
              />
              <div className="mt-4 flex items-center justify-end">
                <button
                  onClick={handleGenerate}
                  disabled={loadingStep === "analyzing" || loadingStep === "drawing"}
                  className={`px-6 py-2 rounded-md text-white font-medium transition-colors ${
                    loadingStep === "analyzing" || loadingStep === "drawing"
                      ? "bg-gray-400 cursor-not-allowed"
                      : "bg-indigo-600 hover:bg-indigo-700"
                  }`}
                >
                  {loadingStep === "analyzing" && "Classifying & Analyzing..."}
                  {loadingStep === "drawing" && "Generating Illustration..."}
                  {loadingStep === "idle" || loadingStep === "done" ? "Generate Content" : ""}
                </button>
              </div>
            </div>
          ) : (
            // UPLOAD MODE (New)
            <div>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Upload a Sign/Notice Image to generate similar questions
                </label>
                <div className="flex items-start space-x-6">
                  <div className="flex-1">
                    <input
                      type="file"
                      ref={fileInputRef}
                      accept="image/*"
                      onChange={handleReferenceUpload}
                      className="block w-full text-sm text-gray-500
                        file:mr-4 file:py-2 file:px-4
                        file:rounded-md file:border-0
                        file:text-sm file:font-semibold
                        file:bg-indigo-50 file:text-indigo-700
                        hover:file:bg-indigo-100"
                    />
                    <p className="mt-2 text-xs text-gray-500">
                      Upload an image and AI will detect if it's a Sign or Notice and suggest 5 new questions.
                    </p>
                  </div>
                  {referenceImage && (
                    <div className="w-32 h-32 border border-gray-300 rounded overflow-hidden bg-gray-50 flex-shrink-0">
                      <img src={referenceImage} alt="Reference" className="w-full h-full object-contain" />
                    </div>
                  )}
                </div>
              </div>

              {isAnalyzingRef && (
                <div className="py-8 text-center text-gray-500 animate-pulse">
                   Analyzing image and generating 5 variations...
                </div>
              )}

              {suggestions.length > 0 && (
                <div className="mt-6">
                  <h3 className="text-lg font-semibold text-gray-800 mb-3">Suggested Questions (Select one to use)</h3>
                  <div className="space-y-3">
                    {suggestions.map((suggestion, idx) => (
                      <div 
                        key={idx}
                        onClick={() => handleSelectSuggestion(suggestion)}
                        className="p-4 border border-gray-200 rounded hover:border-indigo-500 hover:bg-indigo-50 cursor-pointer transition group"
                      >
                        <div className="flex justify-between items-start">
                          <pre className="text-sm text-gray-700 whitespace-pre-wrap font-sans">{suggestion}</pre>
                          <span className="opacity-0 group-hover:opacity-100 text-indigo-600 text-sm font-medium whitespace-nowrap ml-4">
                            Use this &rarr;
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

        </section>

        {/* Error Display */}
        {error && (
          <div className="bg-red-50 text-red-700 p-4 rounded-md border border-red-200">
            <strong>Error:</strong> {error}
          </div>
        )}

        {/* Results Section */}
        {analysisResult && activeTab === "manual" && (
          <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
            <div className="flex justify-between items-center mb-6">
               <div className="flex items-center gap-3">
                 <h2 className="text-xl font-semibold text-gray-800">Preview</h2>
                 <span className={`px-2 py-1 text-xs font-bold uppercase rounded ${
                   analysisResult.type === 'sign' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                 }`}>
                   Detected: {analysisResult.type}
                 </span>
               </div>
               {imageUrl && (
                 <button
                   onClick={handleDownloadDocx}
                   className="flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 text-gray-700 font-medium transition"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                   </svg>
                   <span>Download DOCX</span>
                 </button>
               )}
            </div>

            <div className="flex flex-col md:flex-row gap-8">
              {/* Left Column: Image */}
              <div className="w-full md:w-1/2 flex flex-col items-center">
                <div className="text-sm font-medium text-gray-500 mb-2 w-full">Generated Illustration</div>
                <div className={`w-full bg-gray-100 rounded-md border border-gray-200 flex items-center justify-center overflow-hidden relative ${
                    analysisResult.type === "notice" ? "aspect-video" : "aspect-square"
                }`}>
                   {imageUrl ? (
                     <img src={imageUrl} alt="Generated Sign" className="w-full h-full object-contain p-4" />
                   ) : (
                     <div className="flex flex-col items-center text-gray-400 animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <span>Loading image...</span>
                     </div>
                   )}
                </div>
                <div className="mt-4 p-3 bg-blue-50 text-blue-800 text-xs rounded border border-blue-100 w-full">
                  <strong>AI Description:</strong> {analysisResult.image_description}
                </div>
              </div>

              {/* Right Column: Text */}
              <div className="w-full md:w-1/2">
                 <div className="text-sm font-medium text-gray-500 mb-2">Structured Content</div>
                 <div className="p-6 border border-gray-200 rounded-md bg-gray-50 h-full">
                    <p className="text-lg font-bold mb-6">{analysisResult.docx_content.question}</p>
                    <div className="space-y-3">
                      {Object.entries(analysisResult.docx_content.options).map(([key, val]) => (
                        <div key={key} className="flex items-start">
                          <span className="font-semibold w-8 flex-shrink-0">{key}.</span>
                          <span>{val}</span>
                        </div>
                      ))}
                    </div>
                 </div>
              </div>
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(<App />);

import React, { useState, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Type } from "@google/genai";
import * as docx from "https://esm.sh/docx@8.5.0";

// --- Types ---

interface DocxContent {
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
}

interface AnalysisResult {
  type: "sign" | "notice";
  image_description: string;
  docx_content: DocxContent;
}

// --- Constants ---

const SYSTEM_INSTRUCTION = `You are an educational content generator for English exams.

A teacher will input a multiple-choice question about signs or notices.
The content inside square brackets [ ] is the primary subject.

Your task is a 3-step process:

Step 1: Classification
Identify the type based ONLY on the text inside [ ]:
- "sign": Short, rule-based, command or prohibition. Usually noun phrases or imperatives (e.g., NO PARKING, KEEP OFF).
- "notice": Informational message written in full sentences. Often includes time, reason, or future action (e.g., Closed for renovation. Will reopen next week).

Step 2: Image Description
Create a clear image description suitable for generating an illustration.
- If "sign": Describe a flat, symbolic design with strong visual icons. Minimal or no sentences. High contrast (e.g., Red circle for prohibition).
- If "notice": Describe a simple rectangular notice. You MUST explicitly state the exact text content to be written on the sign (e.g., "A notice with the text: 'Library Closed'"). Focus on the text content.

Step 3: Content Extraction
Prepare structured content for exporting to a DOCX file with the following layout:
Left side: the generated image
Right side: the question text and options A–D

Output your response in JSON format only, following this exact structure:

{
  "type": "sign" | "notice",
  "image_description": "...",
  "docx_content": {
    "question": "...",
    "options": {
      "A": "...",
      "B": "...",
      "C": "...",
      "D": "..."
    }
  }
}

Do NOT explain your reasoning.
Do NOT add extra text outside the JSON.`;

const REFERENCE_ANALYSIS_INSTRUCTION = `You are an assistant for an English teacher. 
The teacher will upload an image of a real-world Sign or Notice.

Your task:
1. Analyze the image to determine if it is a "Sign" (command/symbolic) or a "Notice" (informational text).
2. Generate 5 NEW, SIMILAR exam questions based on the style and context of the image.
3. Each suggestion must follow this exact format:
   "[Description of sign content] The question text...
    A. Option 1
    B. Option 2
    C. Option 3
    D. Option 4"

Return the result as a JSON Object containing an array of strings named "suggestions".`;

// --- App Component ---

const App = () => {
  // Tabs: 'manual' is the existing flow, 'upload' is the new feature
  const [activeTab, setActiveTab] = useState<"manual" | "upload">("manual");

  // Existing State
  const [inputText, setInputText] = useState<string>(
    "[The garden is closed for planting. Will be open to visitors next week] The notice says...\nA. You can visit anytime.\nB. Visitors are allowed now.\nC. Closed for planting.\nD. Open after planting."
  );
  const [loadingStep, setLoadingStep] = useState<
    "idle" | "analyzing" | "drawing" | "done"
  >("idle");
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(
    null
  );
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // New State for Upload Feature
  const [referenceImage, setReferenceImage] = useState<string | null>(null);
  const [isAnalyzingRef, setIsAnalyzingRef] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Helper: Convert Blob to Base64 ---
  const fileToGenerativePart = async (file: File) => {
    const base64EncodedDataPromise = new Promise<string>((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve((reader.result as string).split(",")[1]);
      reader.readAsDataURL(file);
    });
    return {
      inlineData: {
        data: await base64EncodedDataPromise,
        mimeType: file.type,
      },
    };
  };

  // --- New Feature: Analyze Reference Image ---
  const handleReferenceUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Show preview
    const reader = new FileReader();
    reader.onload = (e) => setReferenceImage(e.target?.result as string);
    reader.readAsDataURL(file);

    setIsAnalyzingRef(true);
    setSuggestions([]);
    setError(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key not found.");

      const ai = new GoogleGenAI({ apiKey });

      // Fixed: Removed incorrect call to ai.getGenerativeModel which caused the crash

      const imagePart = await fileToGenerativePart(file);

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: {
          parts: [
            imagePart,
            { text: "Analyze this image and generate 5 similar exam questions." }
          ]
        },
        config: {
          systemInstruction: REFERENCE_ANALYSIS_INSTRUCTION,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestions: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            }
          }
        }
      });

      const result = JSON.parse(response.text || "{}");
      if (result.suggestions && Array.isArray(result.suggestions)) {
        setSuggestions(result.suggestions);
      } else {
        throw new Error("Failed to generate suggestions.");
      }

    } catch (err: any) {
      console.error(err);
      setError("Failed to analyze image. Please try again. " + (err.message || ""));
    } finally {
      setIsAnalyzingRef(false);
    }
  };

  const handleSelectSuggestion = (suggestion: string) => {
    setInputText(suggestion);
    setActiveTab("manual");
    setSuggestions([]);
    setReferenceImage(null);
    // Optional: Reset file input
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  // --- Existing Logic: Generate Content ---
  const handleGenerate = async () => {
    if (!inputText.trim()) return;

    setLoadingStep("analyzing");
    setError(null);
    setAnalysisResult(null);
    setImageUrl(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) {
        throw new Error("API Key not found in environment.");
      }

      const ai = new GoogleGenAI({ apiKey });

      // 1. Analyze Text & Classify
      const analysisModel = "gemini-3-flash-preview";
      const analysisResponse = await ai.models.generateContent({
        model: analysisModel,
        contents: inputText,
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              type: { type: Type.STRING, enum: ["sign", "notice"] },
              image_description: { type: Type.STRING },
              docx_content: {
                type: Type.OBJECT,
                properties: {
                  question: { type: Type.STRING },
                  options: {
                    type: Type.OBJECT,
                    properties: {
                      A: { type: Type.STRING },
                      B: { type: Type.STRING },
                      C: { type: Type.STRING },
                      D: { type: Type.STRING },
                    },
                    required: ["A", "B", "C", "D"],
                  },
                },
                required: ["question", "options"],
              },
            },
            required: ["type", "image_description", "docx_content"],
          },
        },
      });

      const jsonText = analysisResponse.text;
      if (!jsonText) throw new Error("No analysis response generated.");

      const result: AnalysisResult = JSON.parse(jsonText);
      setAnalysisResult(result);

      // 2. Generate Image based on Type
      setLoadingStep("drawing");

      const isNotice = result.type === "notice";
      let imagePrompt = "";

      if (isNotice) {
        // Notice style: Optimized for maximum text legibility
        imagePrompt = `A digital illustration of a simple rectangular NOTICE SIGN. 
        Content: ${result.image_description}.

        CRITICAL VISUAL RULES:
        1. TEXT PRIORITY: The text must be VERY LARGE, BOLD, and BLACK.
        2. FONT: Use a clean, heavy Sans-Serif font (like Arial Bold).
        3. LAYOUT: The text must fill 90% of the image space. Center aligned.
        4. BACKGROUND: Plain white or pale yellow. High contrast against the text.
        5. STYLE: Flat 2D vector. No realistic shading. No background scenery. No glare.

        The goal is for a student to easily read the text on an exam paper.`;
      } else {
        // Sign style: Symbolic, icon-based, minimal text
        imagePrompt = `A flat, simple, educational vector illustration of a SYMBOLIC SIGN: ${result.image_description}. High contrast, clean lines, strong visual icons, no background clutter. Professional exam style.`;
      }

      const imageModel = "gemini-2.5-flash-image";
      const imageResponse = await ai.models.generateContent({
        model: imageModel,
        contents: imagePrompt,
        config: {
          imageConfig: {
            aspectRatio: isNotice ? "16:9" : "1:1", // 16:9 gives more width for sentence-based notices
          },
        },
      });

      // Find image part
      let foundImage = false;
      if (imageResponse.candidates && imageResponse.candidates[0].content.parts) {
        for (const part of imageResponse.candidates[0].content.parts) {
          if (part.inlineData) {
            const base64Data = part.inlineData.data;
            const mimeType = part.inlineData.mimeType || "image/png";
            setImageUrl(`data:${mimeType};base64,${base64Data}`);
            foundImage = true;
            break;
          }
        }
      }

      if (!foundImage) {
        throw new Error("No image generated by the model.");
      }

      setLoadingStep("done");
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred.");
      setLoadingStep("idle");
    }
  };

  const handleDownloadDocx = async () => {
    if (!analysisResult || !imageUrl) return;

    try {
      // 1. Fetch image and process binary data
      const response = await fetch(imageUrl);
      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      // Crucial fix: Convert ArrayBuffer to Uint8Array for docx library
      const imageUint8Array = new Uint8Array(arrayBuffer);

      // Determine image type (default to PNG if unsure)
      const mimeType = blob.type; 
      // docx library expects simple strings like "png", "jpeg", "gif"
      // If generated image is png, use "png", if jpeg, use "jpeg"
      const docxImageType = mimeType.includes("jpeg") || mimeType.includes("jpg") 
        ? "jpeg" 
        : "png";

      const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, ImageRun } = docx;

      // Calculate height based on aspect ratio (Width fixed at 200px approx)
      // 1:1 -> 200px height
      // 16:9 -> ~113px height
      const imageHeight = analysisResult.type === "notice" ? 113 : 200;

      const doc = new Document({
        sections: [
          {
            properties: {},
            children: [
              new Paragraph({
                children: [
                  new TextRun({
                    text: "English Exam - Sign Analysis",
                    bold: true,
                    size: 32, // 16pt
                  }),
                ],
                spacing: { after: 400 },
              }),
              new Table({
                width: {
                  size: 100,
                  type: WidthType.PERCENTAGE,
                },
                rows: [
                  new TableRow({
                    children: [
                      // Cell 1: Image
                      new TableCell({
                        width: {
                          size: 45, // Slightly wider column for image to accommodate 16:9 better
                          type: WidthType.PERCENTAGE,
                        },
                        children: [
                          new Paragraph({
                            children: [
                              new ImageRun({
                                data: imageUint8Array,
                                transformation: {
                                  width: 200,
                                  height: imageHeight, 
                                },
                                type: docxImageType,
                              }),
                            ],
                          }),
                        ],
                      }),
                      // Cell 2: Question and Options
                      new TableCell({
                        width: {
                          size: 55,
                          type: WidthType.PERCENTAGE,
                        },
                        margins: {
                          left: 200, // Twips
                        },
                        children: [
                          new Paragraph({
                            children: [
                              new TextRun({
                                text: analysisResult.docx_content.question,
                                bold: true,
                                size: 24, // 12pt
                              }),
                            ],
                            spacing: { after: 200 },
                          }),
                          ...Object.entries(analysisResult.docx_content.options).map(
                            ([key, value]) =>
                              new Paragraph({
                                children: [
                                  new TextRun({
                                    text: `${key}. ${value}`,
                                    size: 24, // 12pt
                                  }),
                                ],
                              })
                          ),
                        ],
                      }),
                    ],
                  }),
                ],
              }),
            ],
          },
        ],
      });

      const buffer = await Packer.toBlob(doc);
      const url = window.URL.createObjectURL(buffer);
      const a = document.createElement("a");
      a.href = url;
      a.download = "exam-question.docx";
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error("Error creating DOCX:", e);
      setError("Failed to create DOCX file.");
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 p-8">
      <div className="max-w-5xl mx-auto space-y-8">

        {/* Header */}
        <header className="border-b pb-4 border-gray-200">
          <h1 className="text-3xl font-bold text-gray-900">Sign Exam Generator</h1>
          <p className="text-gray-500 mt-2">
            Create exam questions from text descriptions or by analyzing real images.
          </p>
        </header>

        {/* Mode Tabs */}
        <div className="flex space-x-4 border-b border-gray-200">
          <button
            onClick={() => setActiveTab("manual")}
            className={`pb-2 px-4 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "manual"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            Manual Input
          </button>
          <button
            onClick={() => setActiveTab("upload")}
            className={`pb-2 px-4 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "upload"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            Upload Reference Image
          </button>
        </div>

        {/* Input Section - Swaps based on Active Tab */}
        <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">

          {activeTab === "manual" ? (
            // MANUAL INPUT MODE (Existing)
            <div>
              <label htmlFor="questionInput" className="block text-sm font-medium text-gray-700 mb-2">
                Input Question
              </label>
              <textarea
                id="questionInput"
                className="w-full h-32 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
                placeholder="e.g., [NO ENTRY] You cannot enter this road. A. True B. False..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
              />
              <div className="mt-4 flex items-center justify-end">
                <button
                  onClick={handleGenerate}
                  disabled={loadingStep === "analyzing" || loadingStep === "drawing"}
                  className={`px-6 py-2 rounded-md text-white font-medium transition-colors ${
                    loadingStep === "analyzing" || loadingStep === "drawing"
                      ? "bg-gray-400 cursor-not-allowed"
                      : "bg-indigo-600 hover:bg-indigo-700"
                  }`}
                >
                  {loadingStep === "analyzing" && "Classifying & Analyzing..."}
                  {loadingStep === "drawing" && "Generating Illustration..."}
                  {loadingStep === "idle" || loadingStep === "done" ? "Generate Content" : ""}
                </button>
              </div>
            </div>
          ) : (
            // UPLOAD MODE (New)
            <div>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Upload a Sign/Notice Image to generate similar questions
                </label>
                <div className="flex items-start space-x-6">
                  <div className="flex-1">
                    <input
                      type="file"
                      ref={fileInputRef}
                      accept="image/*"
                      onChange={handleReferenceUpload}
                      className="block w-full text-sm text-gray-500
                        file:mr-4 file:py-2 file:px-4
                        file:rounded-md file:border-0
                        file:text-sm file:font-semibold
                        file:bg-indigo-50 file:text-indigo-700
                        hover:file:bg-indigo-100"
                    />
                    <p className="mt-2 text-xs text-gray-500">
                      Upload an image and AI will detect if it's a Sign or Notice and suggest 5 new questions.
                    </p>
                  </div>
                  {referenceImage && (
                    <div className="w-32 h-32 border border-gray-300 rounded overflow-hidden bg-gray-50 flex-shrink-0">
                      <img src={referenceImage} alt="Reference" className="w-full h-full object-contain" />
                    </div>
                  )}
                </div>
              </div>

              {isAnalyzingRef && (
                <div className="py-8 text-center text-gray-500 animate-pulse">
                   Analyzing image and generating 5 variations...
                </div>
              )}

              {suggestions.length > 0 && (
                <div className="mt-6">
                  <h3 className="text-lg font-semibold text-gray-800 mb-3">Suggested Questions (Select one to use)</h3>
                  <div className="space-y-3">
                    {suggestions.map((suggestion, idx) => (
                      <div 
                        key={idx}
                        onClick={() => handleSelectSuggestion(suggestion)}
                        className="p-4 border border-gray-200 rounded hover:border-indigo-500 hover:bg-indigo-50 cursor-pointer transition group"
                      >
                        <div className="flex justify-between items-start">
                          <pre className="text-sm text-gray-700 whitespace-pre-wrap font-sans">{suggestion}</pre>
                          <span className="opacity-0 group-hover:opacity-100 text-indigo-600 text-sm font-medium whitespace-nowrap ml-4">
                            Use this &rarr;
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

        </section>

        {/* Error Display */}
        {error && (
          <div className="bg-red-50 text-red-700 p-4 rounded-md border border-red-200">
            <strong>Error:</strong> {error}
          </div>
        )}

        {/* Results Section */}
        {analysisResult && activeTab === "manual" && (
          <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
            <div className="flex justify-between items-center mb-6">
               <div className="flex items-center gap-3">
                 <h2 className="text-xl font-semibold text-gray-800">Preview</h2>
                 <span className={`px-2 py-1 text-xs font-bold uppercase rounded ${
                   analysisResult.type === 'sign' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                 }`}>
                   Detected: {analysisResult.type}
                 </span>
               </div>
               {imageUrl && (
                 <button
                   onClick={handleDownloadDocx}
                   className="flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 text-gray-700 font-medium transition"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                   </svg>
                   <span>Download DOCX</span>
                 </button>
               )}
            </div>

            <div className="flex flex-col md:flex-row gap-8">
              {/* Left Column: Image */}
              <div className="w-full md:w-1/2 flex flex-col items-center">
                <div className="text-sm font-medium text-gray-500 mb-2 w-full">Generated Illustration</div>
                <div className={`w-full bg-gray-100 rounded-md border border-gray-200 flex items-center justify-center overflow-hidden relative ${
                    analysisResult.type === "notice" ? "aspect-video" : "aspect-square"
                }`}>
                   {imageUrl ? (
                     <img src={imageUrl} alt="Generated Sign" className="w-full h-full object-contain p-4" />
                   ) : (
                     <div className="flex flex-col items-center text-gray-400 animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <span>Loading image...</span>
                     </div>
                   )}
                </div>
                <div className="mt-4 p-3 bg-blue-50 text-blue-800 text-xs rounded border border-blue-100 w-full">
                  <strong>AI Description:</strong> {analysisResult.image_description}
                </div>
              </div>

              {/* Right Column: Text */}
              <div className="w-full md:w-1/2">
                 <div className="text-sm font-medium text-gray-500 mb-2">Structured Content</div>
                 <div className="p-6 border border-gray-200 rounded-md bg-gray-50 h-full">
                    <p className="text-lg font-bold mb-6">{analysisResult.docx_content.question}</p>
                    <div className="space-y-3">
                      {Object.entries(analysisResult.docx_content.options).map(([key, val]) => (
                        <div key={key} className="flex items-start">
                          <span className="font-semibold w-8 flex-shrink-0">{key}.</span>
                          <span>{val}</span>
                        </div>
                      ))}
                    </div>
                 </div>
              </div>
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(<App />);

import React, { useState, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Type } from "@google/genai";
import * as docx from "https://esm.sh/docx@8.5.0";

// --- Types ---

interface DocxContent {
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
}

interface AnalysisResult {
  type: "sign" | "notice";
  image_description: string;
  docx_content: DocxContent;
}

interface BatchItem {
  id: number;
  analysis: AnalysisResult;
  imageUrl: string;
}

// --- Constants ---

const SYSTEM_INSTRUCTION = `You are an educational content generator for English exams.

A teacher will input a multiple-choice question about signs or notices.
The content inside square brackets [ ] is the primary subject.

Your task is a 3-step process:

Step 1: Classification
Identify the type based ONLY on the text inside [ ]:
- "sign": Short, rule-based, command or prohibition. Usually noun phrases or imperatives (e.g., NO PARKING, KEEP OFF).
- "notice": Informational message written in full sentences. Often includes time, reason, or future action (e.g., Closed for renovation. Will reopen next week).

Step 2: Image Description
Create a clear image description suitable for generating an illustration.
- If "sign": Describe a flat, symbolic design with strong visual icons. Minimal or no sentences. High contrast (e.g., Red circle for prohibition).
- If "notice": Describe a simple rectangular notice. You MUST explicitly state the exact text content to be written on the sign (e.g., "A notice with the text: 'Library Closed'"). Focus on the text content.

Step 3: Content Extraction
Prepare structured content for exporting to a DOCX file with the following layout:
Left side: the generated image
Right side: the question text and options A–D

Output your response in JSON format only, following this exact structure:

{
  "type": "sign" | "notice",
  "image_description": "...",
  "docx_content": {
    "question": "...",
    "options": {
      "A": "...",
      "B": "...",
      "C": "...",
      "D": "..."
    }
  }
}

Do NOT explain your reasoning.
Do NOT add extra text outside the JSON.`;

const REFERENCE_ANALYSIS_INSTRUCTION = `You are an assistant for an English teacher. 
The teacher will upload an image of a real-world Sign or Notice.

Your task:
1. Analyze the image to determine if it is a "Sign" (command/symbolic) or a "Notice" (informational text).
2. Generate 5 NEW, SIMILAR exam questions based on the style and context of the image.
3. Each suggestion must follow this exact format:
   "[Description of sign content] The question text...
    A. Option 1
    B. Option 2
    C. Option 3
    D. Option 4"

Return the result as a JSON Object containing an array of strings named "suggestions".`;

// --- Helper: Core Generation Logic ---
// Extracted to be used by both Single and Batch flows
const generateQuestionItem = async (inputText: string, apiKey: string): Promise<{ analysis: AnalysisResult, imageUrl: string }> => {
  const ai = new GoogleGenAI({ apiKey });

  // 1. Analyze Text & Classify
  const analysisModel = "gemini-3-flash-preview";
  const analysisResponse = await ai.models.generateContent({
    model: analysisModel,
    contents: inputText,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          type: { type: Type.STRING, enum: ["sign", "notice"] },
          image_description: { type: Type.STRING },
          docx_content: {
            type: Type.OBJECT,
            properties: {
              question: { type: Type.STRING },
              options: {
                type: Type.OBJECT,
                properties: {
                  A: { type: Type.STRING },
                  B: { type: Type.STRING },
                  C: { type: Type.STRING },
                  D: { type: Type.STRING },
                },
                required: ["A", "B", "C", "D"],
              },
            },
            required: ["question", "options"],
          },
        },
        required: ["type", "image_description", "docx_content"],
      },
    },
  });

  const jsonText = analysisResponse.text;
  if (!jsonText) throw new Error("No analysis response generated.");

  const result: AnalysisResult = JSON.parse(jsonText);

  // 2. Generate Image based on Type
  const isNotice = result.type === "notice";
  let imagePrompt = "";

  if (isNotice) {
    imagePrompt = `A digital illustration of a simple rectangular NOTICE SIGN. 
    Content: ${result.image_description}.

    CRITICAL VISUAL RULES:
    1. TEXT PRIORITY: The text must be VERY LARGE, BOLD, and BLACK.
    2. FONT: Use a clean, heavy Sans-Serif font (like Arial Bold).
    3. LAYOUT: The text must fill 90% of the image space. Center aligned.
    4. BACKGROUND: Plain white or pale yellow. High contrast against the text.
    5. STYLE: Flat 2D vector. No realistic shading. No background scenery. No glare.

    The goal is for a student to easily read the text on an exam paper.`;
  } else {
    imagePrompt = `A flat, simple, educational vector illustration of a SYMBOLIC SIGN: ${result.image_description}. High contrast, clean lines, strong visual icons, no background clutter. Professional exam style.`;
  }

  const imageModel = "gemini-2.5-flash-image";
  const imageResponse = await ai.models.generateContent({
    model: imageModel,
    contents: imagePrompt,
    config: {
      imageConfig: {
        aspectRatio: isNotice ? "16:9" : "1:1",
      },
    },
  });

  let foundImageUrl = "";
  if (imageResponse.candidates && imageResponse.candidates[0].content.parts) {
    for (const part of imageResponse.candidates[0].content.parts) {
      if (part.inlineData) {
        const base64Data = part.inlineData.data;
        const mimeType = part.inlineData.mimeType || "image/png";
        foundImageUrl = `data:${mimeType};base64,${base64Data}`;
        break;
      }
    }
  }

  if (!foundImageUrl) {
    throw new Error("No image generated by the model.");
  }

  return { analysis: result, imageUrl: foundImageUrl };
};

// --- App Component ---

const App = () => {
  // Tabs: 'manual' is the existing flow, 'upload' is the new feature
  const [activeTab, setActiveTab] = useState<"manual" | "upload">("manual");

  // Existing State (Manual Mode)
  const [inputText, setInputText] = useState<string>(
    "[The garden is closed for planting. Will be open to visitors next week] The notice says...\nA. You can visit anytime.\nB. Visitors are allowed now.\nC. Closed for planting.\nD. Open after planting."
  );
  const [loadingStep, setLoadingStep] = useState<
    "idle" | "analyzing" | "drawing" | "done"
  >("idle");
  const [analysisResult, setAnalysisResult] = useState<AnalysisResult | null>(
    null
  );
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  // New State for Upload Feature & Batch
  const [referenceImage, setReferenceImage] = useState<string | null>(null);
  const [isAnalyzingRef, setIsAnalyzingRef] = useState(false);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [batchResults, setBatchResults] = useState<BatchItem[]>([]);
  const [isBatchProcessing, setIsBatchProcessing] = useState(false);
  const [batchProgress, setBatchProgress] = useState("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Helper: Convert Blob to Base64 ---
  const fileToGenerativePart = async (file: File) => {
    const base64EncodedDataPromise = new Promise<string>((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve((reader.result as string).split(",")[1]);
      reader.readAsDataURL(file);
    });
    return {
      inlineData: {
        data: await base64EncodedDataPromise,
        mimeType: file.type,
      },
    };
  };

  // --- Feature: Analyze Reference Image ---
  const handleReferenceUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => setReferenceImage(e.target?.result as string);
    reader.readAsDataURL(file);

    setIsAnalyzingRef(true);
    setSuggestions([]);
    setSelectedIndices(new Set());
    setBatchResults([]);
    setError(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key not found.");

      const ai = new GoogleGenAI({ apiKey });
      const imagePart = await fileToGenerativePart(file);

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: {
          parts: [
            imagePart,
            { text: "Analyze this image and generate 5 similar exam questions." }
          ]
        },
        config: {
          systemInstruction: REFERENCE_ANALYSIS_INSTRUCTION,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestions: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              }
            }
          }
        }
      });

      const result = JSON.parse(response.text || "{}");
      if (result.suggestions && Array.isArray(result.suggestions)) {
        setSuggestions(result.suggestions);
      } else {
        throw new Error("Failed to generate suggestions.");
      }

    } catch (err: any) {
      console.error(err);
      setError("Failed to analyze image. Please try again. " + (err.message || ""));
    } finally {
      setIsAnalyzingRef(false);
    }
  };

  const toggleSelection = (index: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(index)) {
      newSet.delete(index);
    } else {
      newSet.add(index);
    }
    setSelectedIndices(newSet);
  };

  const handleSelectAll = () => {
    if (selectedIndices.size === suggestions.length) {
      setSelectedIndices(new Set());
    } else {
      const newSet = new Set<number>();
      suggestions.forEach((_, i) => newSet.add(i));
      setSelectedIndices(newSet);
    }
  };

  const handleUseSingleSuggestion = (suggestion: string) => {
    setInputText(suggestion);
    setActiveTab("manual");
    setSuggestions([]);
    setReferenceImage(null);
    setSelectedIndices(new Set());
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  // --- Feature: Batch Generation ---
  const handleBatchGenerate = async () => {
    if (selectedIndices.size === 0) return;

    setIsBatchProcessing(true);
    setBatchResults([]);
    setError(null);

    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      setError("API Key not found.");
      setIsBatchProcessing(false);
      return;
    }

    const indicesToProcess = Array.from(selectedIndices).sort((a, b) => a - b);
    const results: BatchItem[] = [];

    try {
      for (let i = 0; i < indicesToProcess.length; i++) {
        const index = indicesToProcess[i];
        const text = suggestions[index];
        setBatchProgress(`Generating question ${i + 1} of ${indicesToProcess.length}...`);

        const { analysis, imageUrl } = await generateQuestionItem(text, apiKey);

        results.push({
          id: index,
          analysis,
          imageUrl
        });

        // Update state incrementally so user sees progress
        setBatchResults([...results]);
      }
    } catch (err: any) {
      console.error(err);
      setError("Error during batch generation: " + (err.message || "Unknown error"));
    } finally {
      setIsBatchProcessing(false);
      setBatchProgress("");
    }
  };

  // --- Existing Logic: Generate Single Content ---
  const handleGenerate = async () => {
    if (!inputText.trim()) return;

    setLoadingStep("analyzing");
    setError(null);
    setAnalysisResult(null);
    setImageUrl(null);

    try {
      const apiKey = process.env.API_KEY;
      if (!apiKey) throw new Error("API Key not found in environment.");

      // Step 1: Analyze & Draw (using helper)
      const { analysis, imageUrl: url } = await generateQuestionItem(inputText, apiKey);

      // Step 2: Set States (Simulating the steps for UI feedback if needed, but helper does it all)
      setAnalysisResult(analysis);
      setLoadingStep("drawing"); // Helper finished both, but we can animate if we want.
      // Small delay just to show "Drawing" state briefly if desired, or jump to done.
      setImageUrl(url);
      setLoadingStep("done");

    } catch (err: any) {
      console.error(err);
      setError(err.message || "An unexpected error occurred.");
      setLoadingStep("idle");
    }
  };

  // --- DOCX Generation Logic ---
  const createDocxBlob = async (items: Array<{analysis: AnalysisResult, imageUrl: string}>) => {
    const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, ImageRun } = docx;

    const sectionsChildren = [
      new Paragraph({
        children: [
          new TextRun({
            text: "English Exam - Sign Analysis",
            bold: true,
            size: 32, // 16pt
          }),
        ],
        spacing: { after: 400 },
      }),
    ];

    for (const item of items) {
      // Fetch image
      const response = await fetch(item.imageUrl);
      const blob = await response.blob();
      const arrayBuffer = await blob.arrayBuffer();
      const imageUint8Array = new Uint8Array(arrayBuffer);
      const mimeType = blob.type; 
      const docxImageType = mimeType.includes("jpeg") || mimeType.includes("jpg") ? "jpeg" : "png";
      const imageHeight = item.analysis.type === "notice" ? 113 : 200;

      // Create Table for this item
      const itemTable = new Table({
        width: {
          size: 100,
          type: WidthType.PERCENTAGE,
        },
        rows: [
          new TableRow({
            children: [
              // Cell 1: Image
              new TableCell({
                width: {
                  size: 45,
                  type: WidthType.PERCENTAGE,
                },
                children: [
                  new Paragraph({
                    children: [
                      new ImageRun({
                        data: imageUint8Array,
                        transformation: {
                          width: 200,
                          height: imageHeight, 
                        },
                        type: docxImageType,
                      }),
                    ],
                  }),
                ],
              }),
              // Cell 2: Question and Options
              new TableCell({
                width: {
                  size: 55,
                  type: WidthType.PERCENTAGE,
                },
                margins: {
                  left: 200, // Twips
                },
                children: [
                  new Paragraph({
                    children: [
                      new TextRun({
                        text: item.analysis.docx_content.question,
                        bold: true,
                        size: 24, // 12pt
                      }),
                    ],
                    spacing: { after: 200 },
                  }),
                  ...Object.entries(item.analysis.docx_content.options).map(
                    ([key, value]) =>
                      new Paragraph({
                        children: [
                          new TextRun({
                            text: `${key}. ${value}`,
                            size: 24, // 12pt
                          }),
                        ],
                      })
                  ),
                ],
              }),
            ],
          }),
        ],
      });

      sectionsChildren.push(itemTable);
      // Add spacing between questions
      sectionsChildren.push(new Paragraph({ spacing: { before: 400 } }));
    }

    const doc = new Document({
      sections: [{ properties: {}, children: sectionsChildren }],
    });

    return await Packer.toBlob(doc);
  };

  const handleDownloadDocx = async () => {
    if (!analysisResult || !imageUrl) return;
    try {
      const blob = await createDocxBlob([{ analysis: analysisResult, imageUrl }]);
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "exam-question.docx";
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error("Error creating DOCX:", e);
      setError("Failed to create DOCX file.");
    }
  };

  const handleBatchDownloadDocx = async () => {
    if (batchResults.length === 0) return;
    try {
      const blob = await createDocxBlob(batchResults.map(r => ({ analysis: r.analysis, imageUrl: r.imageUrl })));
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "exam-questions-batch.docx";
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (e) {
      console.error("Error creating Batch DOCX:", e);
      setError("Failed to create Batch DOCX file.");
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 p-8">
      <div className="max-w-5xl mx-auto space-y-8">

        {/* Header */}
        <header className="border-b pb-4 border-gray-200">
          <h1 className="text-3xl font-bold text-gray-900">Sign Exam Generator</h1>
          <p className="text-gray-500 mt-2">
            Create exam questions from text descriptions or by analyzing real images.
          </p>
        </header>

        {/* Mode Tabs */}
        <div className="flex space-x-4 border-b border-gray-200">
          <button
            onClick={() => setActiveTab("manual")}
            className={`pb-2 px-4 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "manual"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            Manual Input
          </button>
          <button
            onClick={() => setActiveTab("upload")}
            className={`pb-2 px-4 text-sm font-medium transition-colors border-b-2 ${
              activeTab === "upload"
                ? "border-indigo-600 text-indigo-600"
                : "border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300"
            }`}
          >
            Upload Reference Image
          </button>
        </div>

        {/* Input Section - Swaps based on Active Tab */}
        <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">

          {activeTab === "manual" ? (
            // MANUAL INPUT MODE (Existing)
            <div>
              <label htmlFor="questionInput" className="block text-sm font-medium text-gray-700 mb-2">
                Input Question
              </label>
              <textarea
                id="questionInput"
                className="w-full h-32 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
                placeholder="e.g., [NO ENTRY] You cannot enter this road. A. True B. False..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
              />
              <div className="mt-4 flex items-center justify-end">
                <button
                  onClick={handleGenerate}
                  disabled={loadingStep === "analyzing" || loadingStep === "drawing"}
                  className={`px-6 py-2 rounded-md text-white font-medium transition-colors ${
                    loadingStep === "analyzing" || loadingStep === "drawing"
                      ? "bg-gray-400 cursor-not-allowed"
                      : "bg-indigo-600 hover:bg-indigo-700"
                  }`}
                >
                  {loadingStep === "analyzing" && "Classifying & Analyzing..."}
                  {loadingStep === "drawing" && "Generating Illustration..."}
                  {loadingStep === "idle" || loadingStep === "done" ? "Generate Content" : ""}
                </button>
              </div>
            </div>
          ) : (
            // UPLOAD MODE (New with Batch)
            <div>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Upload a Sign/Notice Image to generate similar questions
                </label>
                <div className="flex items-start space-x-6">
                  <div className="flex-1">
                    <input
                      type="file"
                      ref={fileInputRef}
                      accept="image/*"
                      onChange={handleReferenceUpload}
                      className="block w-full text-sm text-gray-500
                        file:mr-4 file:py-2 file:px-4
                        file:rounded-md file:border-0
                        file:text-sm file:font-semibold
                        file:bg-indigo-50 file:text-indigo-700
                        hover:file:bg-indigo-100"
                    />
                    <p className="mt-2 text-xs text-gray-500">
                      Upload an image and AI will detect if it's a Sign or Notice and suggest 5 new questions.
                    </p>
                  </div>
                  {referenceImage && (
                    <div className="w-32 h-32 border border-gray-300 rounded overflow-hidden bg-gray-50 flex-shrink-0">
                      <img src={referenceImage} alt="Reference" className="w-full h-full object-contain" />
                    </div>
                  )}
                </div>
              </div>

              {isAnalyzingRef && (
                <div className="py-8 text-center text-gray-500 animate-pulse">
                   Analyzing image and generating 5 variations...
                </div>
              )}

              {suggestions.length > 0 && !isBatchProcessing && batchResults.length === 0 && (
                <div className="mt-6">
                  <div className="flex justify-between items-center mb-3">
                    <h3 className="text-lg font-semibold text-gray-800">Suggested Questions</h3>
                    <div className="flex space-x-2">
                      <button 
                        onClick={handleSelectAll}
                        className="text-sm text-indigo-600 hover:text-indigo-800 font-medium"
                      >
                         {selectedIndices.size === suggestions.length ? "Deselect All" : "Select All"}
                      </button>
                    </div>
                  </div>

                  <div className="space-y-3">
                    {suggestions.map((suggestion, idx) => {
                      const isSelected = selectedIndices.has(idx);
                      return (
                        <div 
                          key={idx}
                          className={`p-4 border rounded transition flex items-start space-x-3 cursor-pointer ${
                            isSelected ? "border-indigo-500 bg-indigo-50" : "border-gray-200 hover:bg-gray-50"
                          }`}
                          onClick={() => toggleSelection(idx)}
                        >
                          <input 
                            type="checkbox" 
                            checked={isSelected} 
                            onChange={() => {}} // handled by div click
                            className="mt-1 h-4 w-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500" 
                          />
                          <div className="flex-1">
                             <pre className="text-sm text-gray-700 whitespace-pre-wrap font-sans">{suggestion}</pre>
                             <div className="mt-2 text-right">
                               <button 
                                onClick={(e) => { e.stopPropagation(); handleUseSingleSuggestion(suggestion); }}
                                className="text-xs text-indigo-600 hover:underline"
                               >
                                 Edit Individually
                               </button>
                             </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  <div className="mt-6 flex justify-end">
                    <button
                      onClick={handleBatchGenerate}
                      disabled={selectedIndices.size === 0}
                      className={`px-6 py-2 rounded-md text-white font-medium transition-colors ${
                        selectedIndices.size === 0
                          ? "bg-gray-400 cursor-not-allowed"
                          : "bg-indigo-600 hover:bg-indigo-700"
                      }`}
                    >
                      Generate {selectedIndices.size} Selected Questions
                    </button>
                  </div>
                </div>
              )}

              {/* Batch Processing Status */}
              {isBatchProcessing && (
                <div className="py-12 text-center">
                  <div className="inline-block animate-spin rounded-full h-8 w-8 border-4 border-indigo-600 border-t-transparent mb-4"></div>
                  <p className="text-lg font-medium text-gray-700">Generating Batch...</p>
                  <p className="text-gray-500">{batchProgress}</p>
                </div>
              )}

              {/* Batch Results */}
              {batchResults.length > 0 && (
                <div className="mt-8">
                  <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold text-gray-800">Batch Results ({batchResults.length})</h3>
                    <button
                      onClick={handleBatchDownloadDocx}
                      className="flex items-center space-x-2 px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition shadow-sm"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                      </svg>
                      <span>Download All as DOCX</span>
                    </button>
                  </div>

                  <div className="space-y-8">
                    {batchResults.map((result, i) => (
                      <div key={i} className="bg-white p-4 border border-gray-200 rounded-lg shadow-sm">
                        <div className="flex flex-col md:flex-row gap-6">
                          <div className="w-full md:w-1/3 flex-shrink-0">
                            <div className="bg-gray-100 rounded border border-gray-200 aspect-video flex items-center justify-center p-2">
                               <img src={result.imageUrl} alt={`Result ${i+1}`} className="w-full h-full object-contain" />
                            </div>
                          </div>
                          <div className="w-full md:w-2/3">
                            <h4 className="font-bold text-gray-800 mb-2">Question {i+1} ({result.analysis.type})</h4>
                            <p className="font-medium mb-3">{result.analysis.docx_content.question}</p>
                            <ul className="space-y-1 text-sm text-gray-600">
                               <li>A. {result.analysis.docx_content.options.A}</li>
                               <li>B. {result.analysis.docx_content.options.B}</li>
                               <li>C. {result.analysis.docx_content.options.C}</li>
                               <li>D. {result.analysis.docx_content.options.D}</li>
                            </ul>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="mt-6 flex justify-center">
                    <button 
                      onClick={() => { setBatchResults([]); setSelectedIndices(new Set()); setSuggestions([]); setReferenceImage(null); }}
                      className="text-gray-500 hover:text-gray-800 underline"
                    >
                      Start Over
                    </button>
                  </div>
                </div>
              )}

            </div>
          )}

        </section>

        {/* Error Display */}
        {error && (
          <div className="bg-red-50 text-red-700 p-4 rounded-md border border-red-200">
            <strong>Error:</strong> {error}
          </div>
        )}

        {/* Results Section (Single Manual) */}
        {analysisResult && activeTab === "manual" && (
          <section className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
            <div className="flex justify-between items-center mb-6">
               <div className="flex items-center gap-3">
                 <h2 className="text-xl font-semibold text-gray-800">Preview</h2>
                 <span className={`px-2 py-1 text-xs font-bold uppercase rounded ${
                   analysisResult.type === 'sign' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'
                 }`}>
                   Detected: {analysisResult.type}
                 </span>
               </div>
               {imageUrl && (
                 <button
                   onClick={handleDownloadDocx}
                   className="flex items-center space-x-2 px-4 py-2 border border-gray-300 rounded-md hover:bg-gray-50 text-gray-700 font-medium transition"
                 >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-blue-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                   </svg>
                   <span>Download DOCX</span>
                 </button>
               )}
            </div>

            <div className="flex flex-col md:flex-row gap-8">
              {/* Left Column: Image */}
              <div className="w-full md:w-1/2 flex flex-col items-center">
                <div className="text-sm font-medium text-gray-500 mb-2 w-full">Generated Illustration</div>
                <div className={`w-full bg-gray-100 rounded-md border border-gray-200 flex items-center justify-center overflow-hidden relative ${
                    analysisResult.type === "notice" ? "aspect-video" : "aspect-square"
                }`}>
                   {imageUrl ? (
                     <img src={imageUrl} alt="Generated Sign" className="w-full h-full object-contain p-4" />
                   ) : (
                     <div className="flex flex-col items-center text-gray-400 animate-pulse">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <span>Loading image...</span>
                     </div>
                   )}
                </div>
                <div className="mt-4 p-3 bg-blue-50 text-blue-800 text-xs rounded border border-blue-100 w-full">
                  <strong>AI Description:</strong> {analysisResult.image_description}
                </div>
              </div>

              {/* Right Column: Text */}
              <div className="w-full md:w-1/2">
                 <div className="text-sm font-medium text-gray-500 mb-2">Structured Content</div>
                 <div className="p-6 border border-gray-200 rounded-md bg-gray-50 h-full">
                    <p className="text-lg font-bold mb-6">{analysisResult.docx_content.question}</p>
                    <div className="space-y-3">
                      {Object.entries(analysisResult.docx_content.options).map(([key, val]) => (
                        <div key={key} className="flex items-start">
                          <span className="font-semibold w-8 flex-shrink-0">{key}.</span>
                          <span>{val}</span>
                        </div>
                      ))}
                    </div>
                 </div>
              </div>
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

const root = createRoot(document.getElementById("root")!);
root.render(<App />);

