           <p className="mb-2 font-medium text-gray-300">English Exam Content Generator</p>
           <p className="text-sm">
             &copy; {new Date().getFullYear()} All rights reserved. Powered by Google Gemini.
           </p>
        </div>
      </footer>
    </div>
  );
};

